using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        Uri = "config://app/settings",
        Name = "App Settings",
        Description = "Returns the current application configuration data")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "Production",
            Version = "1.2.0",
            Features = new { DarkMode = true, BetaAccess = false },
            MaxConnections = 100
        };
        return System.Text.Json.JsonSerializer.Serialize(config, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/settings/{section}",
        Name = "App Settings Section",
        Description = "Returns a specific configuration section")]
    public static string GetSettingsSection(string section)
    {
        return section.ToLower() switch
        {
            "database" => System.Text.Json.JsonSerializer.Serialize(new { Host = "db.example.com", Port = 5432, Name = "appdb" }),
            "logging" => System.Text.Json.JsonSerializer.Serialize(new { Level = "Information", Sink = "Console" }),
            _ => System.Text.Json.JsonSerializer.Serialize(new { Error = $"Unknown section: {section}" })
        };
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class GreetingTool
{
    [McpServerTool(Name = "greet"), Description("Greets a user by name")]
    public static string Greet([Description("The name to greet")] string name)
    {
        return $"Hello, {name}! Welcome to the MCP HTTP server.";
    }
}

